def _backfill_accounts() -> None:
    """Existing customers with a valid Indian mobile number get a customer_account (one per phone)."""
    cust = sa.table("customers", sa.column("id", sa.Uuid), sa.column("name", sa.String), sa.column("phone", sa.String),
                    sa.column("customer_account_id", sa.Uuid))
    acc = sa.table("customer_accounts", sa.column("id", sa.Uuid), sa.column("phone", sa.String),
                   sa.column("name", sa.String), sa.column("created_at", sa.DateTime(timezone=True)))
    conn = op.get_bind()
    by_phone: dict = {}
    for row in conn.execute(sa.select(cust.c.id, cust.c.name, cust.c.phone)).all():
        digits = "".join(ch for ch in row.phone or "" if ch.isdigit())
        e164 = "+91" + digits if len(digits) == 10 and digits[0] in "6789" else (
            "+" + digits if len(digits) == 12 and digits.startswith("91") else None)
        if e164 is None:
            continue
        if e164 not in by_phone:
            by_phone[e164] = uuid.uuid4()
            conn.execute(acc.insert().values(id=by_phone[e164], phone=e164, name=row.name,
                                             created_at=datetime.now(timezone.utc)))
        conn.execute(cust.update().where(cust.c.id == row.id).values(customer_account_id=by_phone[e164]))


